mapper.select:
SELECT b.id AS booking_id, b.booking_code, b.booking_status, b.check_in_date, b.check_out_date,
       SUM(i.quantity) AS quantity, b.updated_at
FROM hotel_booking_items i
JOIN hotel_bookings b ON b.id = i.booking_id
WHERE i.room_type_id = #{roomTypeId}
  AND b.booking_status IN ('CONFIRMED', 'CHECKED_IN')
  AND b.check_out_date >= #{fromDate}
GROUP BY b.id, b.booking_code, b.booking_status, b.check_in_date, b.check_out_date, b.updated_at
ORDER BY b.check_in_date, b.id
LIMIT #{limit}

SELECT inventory_date
FROM room_inventory_daily
WHERE room_type_id = #{roomTypeId}
  AND stop_sell = TRUE
  AND inventory_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY inventory_date
LIMIT #{limit}
